// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

contract FixedUpgradeable is Initializable, OwnableUpgradeable {
    function initialize() external initializer {
        __Ownable_init_unchained(); // @audit correct unchained initializer
    }

    function executeDiamondCut(DiamondCutData calldata _cut) external onlyGovernor {
        require(proposedHash == keccak256(abi.encode(_cut.facetCuts, _cut.initAddress, _cut.initCalldata)), "hash mismatch");
        diamondCut(_cut);
    }

    function stopRent(RentalOrder calldata order) external {
        store.removeRentals(deriveHash(order), updates); // @audit storage update first
        _removeHooks(order.hooks, order.items, order.rentalWallet);
        _reclaimRentedItems(order);
        ESCROW.settlePayment(order);
    }

    function checkTransaction(bytes calldata data) external {
        if (data.length > 0 && data.length < 4) revert("selector required"); // @audit allows empty calldata
    }
}
